const pages={
 public:[['home','产品首页'],['flow','产品能力与使用流程'],['sample-report','示例报告'],['pricing','Free / Pro 套餐'],['faq','FAQ'],['auth','登录 / 注册']],
 candidate:[['onboarding','新手引导与目标设置'],['dashboard','学习 Dashboard'],['questions','面试题库'],['question-detail','题目详情'],['practice','单题练习'],['focus-practice','专项练习与错题'],['interview-config','模拟面试配置'],['interview-plan','面试计划确认'],['text-room','文本面试室'],['voice-room','语音面试室'],['session-control','暂停、恢复与结束'],['report-overview','面试报告总览'],['report-evidence','逐题证据与评分'],['learning-plan','弱项与学习计划'],['progress','复测与进步趋势'],['usage','套餐、额度和用量'],['privacy','账号、隐私与数据']],
 admin:[['admin-content','题目 / Rubric 列表'],['admin-editor','创建和编辑题目'],['admin-review','内容审核与版本发布'],['admin-provider','Provider 状态与成本'],['admin-golden','Golden Set 与评测质量'],['admin-complaints','用户投诉与评分纠错'],['admin-deletion','隐私删除请求'],['admin-audit','敏感访问审计']],
 decisions:[['decisions','产品决策中心']]
};
const stateLabels=['默认','首次进入','空状态','加载中','局部加载','搜索无结果','表单错误','未登录','无权限','Session 过期','麦克风未授权','麦克风拒绝','无麦克风设备','ASR 转写中','低置信技术术语','用户修正转写','TTS 播放中','ASR 服务失败','TTS 服务失败','LLM 服务失败','自动降级到文本','网络断开','恢复成功','重复提交','面试暂停','主动结束确认','报告生成中','证据不足','额度不足','删除请求处理中','删除部分失败','管理员访问需要 reason code'];
let state={page:location.hash.slice(1)||'home',role:localStorage.getItem('mock-role')||'candidate',view:'默认',voice:'intro',paused:false,turn:1,query:'',modal:null};
const allPages=[...pages.public,...pages.candidate,...pages.admin,...pages.decisions];
const labels=Object.fromEntries(allPages);
const icons={public:'P',candidate:'U',admin:'A',decisions:'D'};
function esc(s){return String(s).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function btn(label,action='toast',kind=''){return `<button type="button" class="btn ${kind}" data-action="${action}">${label}</button>`}
function tag(text,kind=''){return `<span class="tag ${kind}">${text}</span>`}
function notice(title,text,kind='info'){return `<div class="notice ${kind}" role="status"><span aria-hidden="true">${kind==='danger'?'!':kind==='warning'?'△':'i'}</span><div><strong>${title}</strong>${text?`<span>${text}</span>`:''}</div></div>`}
function metric(label,val){return `<div class="metric-row"><span>${label}</span><div class="metric-bar"><span style="width:${val}%"></span></div><strong class="mono">${val}</strong></div>`}
function pageHead(eyebrow,title,lede,actions=''){return `<header class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="lede">${lede}</p></div>${actions?`<div class="btn-row">${actions}</div>`:''}</header>`}
function shell(content){
 if(pages.public.some(p=>p[0]===state.page)) return `<div class="public"><header class="landing-nav"><a href="#home" class="brand"><span class="brand-mark">AI</span><span style="color:#172033">Interview Coach</span></a><nav class="links" aria-label="公开区导航">${pages.public.slice(1,5).map(([id,l])=>`<a href="#${id}">${l}</a>`).join('')}</nav><div class="btn-row">${btn('登录','goto-auth')}${btn('开始体验','goto-onboarding','primary')}</div></header><main id="main-content" class="page" tabindex="-1">${content}</main><footer class="footer">交互原型 · 全部数据为 Mock · 练习反馈，不是招聘结论 · 不提供真实面试隐蔽代答</footer>${modal()}</div>`;
 const currentRole=pages.admin.some(p=>p[0]===state.page)?'admin':'candidate';
 return `<div class="app-shell"><aside class="sidebar"><a href="#dashboard" class="brand"><span class="brand-mark">AI</span><span>Interview Coach</span></a><div class="role-switch" role="group" aria-label="视角切换"><button data-role="candidate" class="${currentRole==='candidate'?'active':''}">求职者视角</button><button data-role="admin" class="${currentRole==='admin'?'active':''}">管理员视角</button></div><nav aria-label="主要导航">${navGroup(currentRole==='admin'?pages.admin:pages.candidate,currentRole==='admin'?'管理后台':'学习工作台')}${navGroup(pages.decisions,'产品评审')}${navGroup(pages.public,'公开区')}</nav><div class="sidebar-footer">Mock 原型 v1<br>不会连接后端或上传数据</div></aside><div class="main"><header class="topbar"><div><strong>${labels[state.page]||'原型'}</strong><span class="context"> · ${state.view}</span></div><div class="topbar-actions">${btn('状态实验室','state-lab','small')}<span class="avatar" aria-label="Mock 用户 林默">林</span></div></header><main id="main-content" class="page" tabindex="-1">${content}</main></div>${modal()}</div>`;
}
function navGroup(items,label){return `<div class="nav-label">${label}</div><div class="nav-group">${items.map(([id,l])=>`<a class="nav-item ${state.page===id?'active':''}" href="#${id}" ${state.page===id?'aria-current="page"':''}><span class="nav-icon">${icons[label==='公开区'?'public':label==='产品评审'?'decisions':label==='管理后台'?'admin':'candidate']}</span>${l}</a>`).join('')}</div>`}
function modal(){if(!state.modal)return'';if(state.modal==='state')return `<div class="modal-backdrop" data-action="close-modal"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="state-title" onclick="event.stopPropagation()"><div class="modal-head"><div><h2 id="state-title">状态实验室</h2><p class="muted small">切换当前页面的异常与边界状态。状态仅为浏览器 Mock。</p></div><button class="close" data-action="close-modal" aria-label="关闭状态实验室">×</button></div><div class="chip-row">${stateLabels.map(s=>`<button class="btn small ${state.view===s?'primary':''}" data-view="${s}">${s}</button>`).join('')}</div></section></div>`;return `<div class="modal-backdrop" data-action="close-modal"><section class="modal" role="dialog" aria-modal="true" onclick="event.stopPropagation()">${state.modal}</section></div>`}
function applyGlobalState(content){
 const v=state.view;if(v==='默认')return content;
 if(v==='加载中')return pageHead('状态预览','页面加载中','正在读取明确标记的 Mock 数据。')+`<div class="grid grid-3">${[1,2,3].map(()=>`<div class="card"><div class="skeleton" style="width:45%"></div><div class="skeleton" style="margin-top:18px;height:80px"></div><div class="skeleton" style="margin-top:14px;width:70%"></div></div>`).join('')}</div>`;
 if(v==='空状态')return pageHead('状态预览','这里还没有内容','完成首次练习后，此处会显示个性化内容。')+`<div class="empty"><h2>从第一道题开始</h2><p class="muted">Mock 空态保留清晰的下一步，不制造虚假数据。</p>${btn('浏览题库','goto-questions','primary')}</div>`;
 if(v==='未登录'||v==='Session 过期'||v==='无权限')return pageHead('访问状态',v,v==='未登录'?'登录后才能访问个人练习记录。':v==='Session 过期'?'为保护学习数据，请重新登录。':'当前角色没有查看此页面的权限。')+notice(v,v==='无权限'?'切换到有权限的视角，或返回可访问页面。':'Mock 不会提交账号信息。','warning')+`<div class="section btn-row">${btn('前往登录','goto-auth','primary')}${btn('返回首页','goto-home')}</div>`;
 if(v==='网络断开')return notice('网络已断开','已提交的 Mock 回答保留在最近恢复点；恢复后不会重复扣减额度。','danger')+content;
 if(v==='恢复成功')return notice('恢复成功','已回到第 2 题最近持久化轮次，没有重复提问或扣费。','success')+content;
 if(v==='额度不足')return notice('额度不足','本次预计消耗 12 分钟，当前剩余 6 分钟。可切换文本或升级套餐。','warning')+content;
 if(v==='重复提交')return notice('已收到相同提交','返回第一次 Mock 结果，不重复处理或扣减。','info')+content;
 return notice(`当前状态：${v}`,'这是供产品评审的 Mock 状态，不代表真实服务行为。',v.includes('失败')||v.includes('拒绝')?'danger':'warning')+content;
}
function render(){state.page=labels[state.page]?state.page:'home';const content=applyGlobalState(pageContent(state.page));document.getElementById('app').innerHTML=shell(content);bind();requestAnimationFrame(()=>document.getElementById('main-content')?.focus({preventScroll:true}))}
function pageContent(id){
 switch(id){
 case'home':return `<section class="hero"><div class="eyebrow">面向 Java 开发者的 AI 转型训练</div><h1>不是背答案，而是练会解释、取舍与追问。</h1><p class="lede">从高质量题库到模拟面试、证据化报告与弱项复测。所有评分都回到 Rubric 和你的原话。</p><div class="btn-row" style="margin-top:24px">${btn('开始 10 分钟短练','goto-onboarding','primary')}${btn('查看示例报告','goto-sample')}</div></section><section class="section grid grid-3"><article class="card"><div class="eyebrow">01 · 练</div><h2>转型路径题库</h2><p class="muted">Java、AI 应用、RAG、Agent、工作流、MCP、评测安全与系统设计。</p></article><article class="card"><div class="eyebrow">02 · 讲</div><h2>有限追问面试</h2><p class="muted">文本为稳定底座，语音采用可降级的级联 Mock 流程。</p></article><article class="card"><div class="eyebrow">03 · 改</div><h2>证据化反馈</h2><p class="muted">正确、部分、错误与证据不足分开，行动建议可直接进入复测。</p></article></section>${notice('产品边界','练习反馈，不是招聘结论；不提供真实面试隐蔽代答。','info')}`;
 case'flow':return pageHead('公开区','产品能力与使用流程','用一个闭环完成“选题—作答—追问—报告—复测”。')+`<div class="timeline">${[['1','设置目标','选择 Java 年限、AI 经验、目标岗位与级别'],['2','练题或模拟面试','文本模式稳定可用，语音失败可降级'],['3','查看证据报告','Rubric、用户原话、置信限制与建议'],['4','加入学习计划','弱项变成专项练习与复测日期']].map(x=>`<div class="timeline-item"><div class="dot">${x[0]}</div><div class="card"><h2>${x[1]}</h2><p class="muted">${x[2]}</p></div></div>`).join('')}</div>`;
 case'sample-report':case'report-overview':return reportOverview(id==='sample-report');
 case'pricing':return pricing();
 case'faq':return faq();
 case'auth':return auth();
 case'onboarding':return onboarding();
 case'dashboard':return dashboard();
 case'questions':return questions();
 case'question-detail':return questionDetail();
 case'practice':return practice();
 case'focus-practice':return focusPractice();
 case'interview-config':return interviewConfig();
 case'interview-plan':return interviewPlan();
 case'text-room':return textRoom();
 case'voice-room':return voiceRoom();
 case'session-control':return sessionControl();
 case'report-evidence':return reportEvidence();
 case'learning-plan':return learningPlan();
 case'progress':return progress();
 case'usage':return usage();
 case'privacy':return privacy();
 case'admin-content':return adminContent();
 case'admin-editor':return adminEditor();
 case'admin-review':return adminReview();
 case'admin-provider':return adminProvider();
 case'admin-golden':return adminGolden();
 case'admin-complaints':return adminComplaints();
 case'admin-deletion':return adminDeletion();
 case'admin-audit':return adminAudit();
 case'decisions':return decisions();
 }
}
function pricing(){return pageHead('公开区','Free / Pro 套餐','定价仅用于范围讨论，不连接真实支付。')+notice('Mock 商业化边界','平台故障、Provider 失败和幂等重复提交不扣费；开始前展示预计消耗。','info')+`<div class="section grid grid-3"><div class="card"><h2>Free</h2><div class="stat">¥0</div><p>文本面试 3 场 / 月<br>语音 10 分钟 / 月<br>基础证据报告</p>${btn('选择 Free','toast','')}</div><div class="card" style="border:2px solid var(--primary)"><div class="tag primary">推荐讨论项</div><h2>Pro</h2><div class="stat">¥59<span class="small"> / 月</span></div><p>文本面试 20 场<br>语音 120 分钟<br>深度报告、趋势和复测</p>${btn('选择 Pro Mock','toast','primary')}</div><div class="card"><h2>本次预计</h2><div class="stat">12<span class="small"> 分钟</span></div><p>剩余额度：26 分钟<br>预计结束后：14 分钟</p>${btn('查看用量规则','goto-usage')}</div></div>`}
function faq(){return pageHead('公开区','常见问题','集中说明评分、语音、隐私、额度与求职诚信边界。')+`<div class="grid">${[['这是招聘结论吗？','不是。报告是带证据限制的练习反馈，不能替代招聘决策。'],['可以在真实面试中实时提示吗？','不可以。产品不提供隐蔽代答、悬浮窗提示或规避检测。'],['会保存原始音频吗？','原型不录音。规划方向是转写成功后尽快删除，具体 SLA 待批准。'],['平台失败会扣费吗？','不会。Mock 账本显示预留释放；真实规则尚未实现。']].map(x=>`<details class="card"><summary><strong>${x[0]}</strong></summary><p class="muted">${x[1]}</p></details>`).join('')}</div>`}
function auth(){return pageHead('账号','登录 / 注册','原型不会提交或保存邮箱、密码与验证码。')+`<div class="grid grid-2"><form class="card" data-form><h2>登录</h2><div class="field ${state.view==='表单错误'?'error':''}"><label for="email">邮箱</label><input id="email" type="email" autocomplete="email" value="mock@example.com">${state.view==='表单错误'?'<span class="field-error" role="alert">请输入有效邮箱地址</span>':''}</div><div class="field" style="margin-top:14px"><label for="password">密码</label><input id="password" type="password" autocomplete="current-password" value="mock-only"></div><div class="btn-row" style="margin-top:18px">${btn('登录 Mock 账号','login','primary')}${btn('忘记密码','toast')}</div></form><div class="card"><h2>创建账号</h2><p class="muted">注册前将展示服务协议与隐私政策版本。当前不接短信、微信或第三方登录。</p>${notice('隐私提示','不要在原型中填写真实个人信息。','warning')}${btn('开始注册流程','goto-onboarding','primary')}</div></div>`}
function onboarding(){return pageHead('首次进入','设定你的转型目标','3 步建立 Mock 学习档案，可随时返回修改。')+`<div class="progress"><span style="width:66%"></span></div><form class="card section"><div class="form-grid"><div class="field"><label for="years">Java 经验</label><select id="years"><option>3–5 年</option><option>1–3 年</option><option>5 年以上</option></select></div><div class="field"><label for="target">目标岗位</label><select id="target"><option>AI Agent 开发工程师</option><option>AI 应用开发工程师</option><option>Java 后端工程师</option></select></div><div class="field full"><label>重点方向</label><div class="chip-row">${['AI 应用','RAG','Agent','工作流','MCP','评测安全','系统设计'].map((x,i)=>`<label class="option"><input type="checkbox" ${i<5?'checked':''}>${x}</label>`).join('')}</div></div></div><div class="btn-row" style="margin-top:20px">${btn('保存并进入 Dashboard','goto-dashboard','primary')}${btn('稍后设置','goto-dashboard')}</div></form>`}
function dashboard(){return pageHead('学习工作台','晚上好，林默','围绕“Java → AI Agent 开发”的 Mock 学习路径。',btn('继续未完成面试','goto-text','primary'))+`<div class="grid grid-4"><div class="card"><div class="muted small">今日任务</div><div class="stat">3</div><span class="status info">1 项待复测</span></div><div class="card"><div class="muted small">连续练习</div><div class="stat">6 天</div><span class="muted small">无羞辱性提醒</span></div><div class="card"><div class="muted small">最近反馈</div><div class="stat">72</div><span class="status warning">练习反馈</span></div><div class="card"><div class="muted small">Pro 语音</div><div class="stat">26</div><span class="muted small">分钟剩余</span></div></div><div class="section grid grid-2"><div class="card"><h2>能力概览</h2>${metric('Java 工程',78)}${metric('RAG',64)}${metric('Agent',58)}${metric('评测安全',43)}</div><div class="card"><h2>优先行动</h2><div class="timeline"><div class="timeline-item"><div class="dot">1</div><div><strong>补齐 Agent 恢复策略</strong><p class="muted small">来自最近报告中的部分正确项</p>${btn('加入专项练习','add-plan','small')}</div></div><div class="timeline-item"><div class="dot">2</div><div><strong>复测 RAG 召回定位</strong><p class="muted small">明天 · 预计 8 分钟</p>${btn('开始复测','goto-practice','small')}</div></div></div></div></div>`}
function questions(){let qs=MOCK.questions.filter(q=>!state.query||q.title.toLowerCase().includes(state.query.toLowerCase())||q.domain.includes(state.query));if(state.view==='搜索无结果')qs=[];return pageHead('题库','面试题库','按转型路径筛选，每题包含来源、版本、Rubric 与追问预算。',btn('查看错题','goto-focus'))+`<div class="filterbar"><div class="search"><span aria-hidden="true">⌕</span><label class="tiny" for="q-search" style="position:absolute;clip:rect(0,0,0,0)">搜索题库</label><input id="q-search" placeholder="搜索题干、知识点或技术名" value="${esc(state.query)}"></div>${['Java','AI 应用','RAG','Agent','工作流','MCP','评测安全','系统设计'].map(x=>`<button class="btn small" data-search="${x}">${x}</button>`).join('')}</div>${qs.length?`<div class="grid grid-2">${qs.map(q=>`<article class="card interactive"><div class="section-head"><div>${tag(q.domain,'primary')} ${tag(q.level)}</div><span class="status ${q.status==='已掌握'?'success':q.status==='待复测'?'warning':'info'}">${q.status}</span></div><h2>${q.title}</h2><p class="muted small">${q.id} · ${q.time} · ${q.source}</p><div class="chip-row">${q.tags.map(t=>tag(t)).join('')}</div><div class="btn-row" style="margin-top:16px">${btn('查看题目','goto-question','primary')}${btn('开始练习','goto-practice')}</div></article>`).join('')}</div>`:`<div class="empty"><h2>没有匹配结果</h2><p class="muted">尝试清除关键词或选择更宽的方向。</p>${btn('清除筛选','clear-search','primary')}</div>`}`}
function questionDetail(){return pageHead('Q-1042 · RAG','RAG 召回质量下降时，你会如何定位？','中级 · 预计 8 分钟 · 发布版本 v0.3',btn('开始作答','goto-practice','primary'))+`<div class="grid grid-2"><article class="card"><h2>场景与回答要求</h2><p>线上 RAG 应用的用户反馈“最近回答经常找不到依据”，但索引任务没有明显报错。请说明定位顺序、核心指标和至少两个可能根因。</p>${notice('先答后看','提交答案后解锁完整答案要点与 Rubric。','info')}<div class="section"><h3>前置知识</h3><div class="chip-row">${['召回率','重排','Embedding','索引更新','Golden Set'].map(x=>tag(x)).join('')}</div></div></article><aside class="card"><h2>内容可信信息</h2><p class="small">来源：内部 RAG 评测实践<br>最近审核：2026-07-28<br>Rubric：v0.3<br>追问预算：2 次</p>${btn('报告题目问题','toast')}</aside></div>`}
function practice(){return pageHead('单题练习','构建你的回答','建议先给出定位框架，再说明指标、假设与验证顺序。')+`<div class="grid grid-2"><div class="card"><h2>你的回答</h2><div class="field"><label for="answer">文本回答</label><textarea id="answer">我会先区分检索问题和生成问题。检索侧先看 Recall@K、索引更新时间和查询分布，再对比最近 Embedding 或切分策略变化……</textarea><span class="muted tiny">Mock 草稿只保存在当前浏览器会话。</span></div><div class="btn-row" style="margin-top:14px">${btn('提交并获取反馈','submit-answer','primary')}${btn('语音作答 Mock','goto-voice')}</div></div><div class="card"><h2>反馈预览</h2>${state.view==='证据不足'?notice('证据不足','回答没有说明如何区分召回与重排，暂不判断该项。','warning'):`${metric('问题理解',82)}${metric('定位结构',74)}${metric('工程取舍',61)}`}<div class="evidence section"><strong>用户原话证据</strong><p class="quote">“我会先区分检索问题和生成问题。”</p><span class="status success">正确：先拆链路</span></div>${btn('加入错题与复测','add-plan','small')}</div></div>`}
function focusPractice(){return pageHead('学习闭环','专项练习与错题','按弱项聚合，而不是只重复同一道题。')+`<div class="grid grid-3">${[['Agent 恢复与补偿','6 题','来自 2 次部分正确'],['RAG 召回评测','4 题','明天复测'],['评测安全','5 题','证据量不足']].map((x,i)=>`<div class="card"><span class="tag ${i===2?'warning':'primary'}">${x[1]}</span><h2>${x[0]}</h2><p class="muted small">${x[2]}</p>${btn(i===1?'开始复测':'开始专项','goto-practice','primary')}</div>`).join('')}</div>`}
function interviewConfig(){return pageHead('模拟面试','配置一场专属面试','选择范围、时长和模式；开始前会展示预计消耗与恢复规则。')+`<form class="card"><div class="form-grid"><div class="field"><label for="role">目标岗位</label><select id="role"><option>AI Agent 开发工程师</option></select></div><div class="field"><label for="level">目标级别</label><select id="level"><option>中级</option><option>高级</option></select></div><div class="field full"><label>技术范围</label><div class="chip-row">${['Java','AI 应用','RAG','Agent','工作流','MCP','评测安全','系统设计'].map((x,i)=>`<label class="option"><input type="checkbox" ${i>1&&i<6?'checked':''}>${x}</label>`).join('')}</div></div><div class="field"><label for="duration">面试时长</label><select id="duration"><option>20 分钟 · 约 4 题</option><option>40 分钟 · 约 7 题</option></select></div><div class="field"><label for="mode">交互模式</label><select id="mode"><option>文本</option><option>级联语音（可降级）</option></select></div></div><div class="section">${notice('预计消耗','文本 1 场；若切换语音，预计 18–22 分钟。当前语音剩余 26 分钟。','info')}</div><div class="btn-row">${btn('生成面试计划','goto-plan','primary')}${btn('保存为模板','toast')}</div></form>`}
function interviewPlan(){return pageHead('开始前确认','确认面试计划','问题在开始后锁定版本；可暂停、恢复或主动结束。')+`<div class="grid grid-2"><div class="card"><h2>20 分钟计划</h2><div class="timeline">${[['1','RAG 召回与评测','主问题 + 1 次追问 · 6 分钟'],['2','Agent 状态恢复','主问题 + 2 次追问 · 8 分钟'],['3','MCP 权限边界','主问题 · 6 分钟']].map(x=>`<div class="timeline-item"><div class="dot">${x[0]}</div><div><strong>${x[1]}</strong><p class="muted small">${x[2]}</p></div></div>`).join('')}</div></div><div class="card"><h2>开始前确认</h2>${notice('恢复规则','网络中断后回到最近持久化轮次，幂等重复提交不重复扣费。','info')}<label class="checkbox section"><input type="checkbox" checked><span>我知道这是练习反馈，不是招聘结论。</span></label><label class="checkbox"><input type="checkbox" checked><span>我不会把本产品用于真实面试隐蔽代答。</span></label><div class="btn-row section">${btn('开始文本面试','goto-text','primary')}${btn('改为语音','goto-voice')}</div></div></div>`}
function textRoom(){return `<div class="interview-shell">${pageHead('面试中 · 文本','RAG 与 Agent 专项','Mock 会话 · 第 2 / 4 题',btn(state.paused?'继续面试':'暂停','pause')+btn('结束','end','danger'))}<div class="room-bar"><span>AI Agent 开发工程师 · 中级</span><span class="mono">12:48</span></div><div class="room"><section class="chat" aria-label="面试对话"><div class="bubble ai"><strong>面试官</strong><br>如果一个 Agent 在工具调用成功后进程崩溃，恢复时如何避免重复执行副作用？</div><div class="bubble user">我会给工具调用设计幂等键，并把调用意图和结果写入持久化状态。恢复时先按幂等键查询，再决定补偿或继续。</div><div class="bubble ai"><strong>追问 1 / 2</strong><br>如果外部系统不支持幂等键，你会怎样设计回读与补偿？</div><div class="composer"><label for="room-answer" class="tiny muted">回答当前追问</label><textarea id="room-answer" placeholder="输入回答，Ctrl + Enter 发送"></textarea><div class="btn-row">${btn('发送回答','send-answer','primary')}${btn('跳过本题','toast')}</div></div></section><aside class="room-aside"><h2>当前进度</h2><div class="progress"><span style="width:46%"></span></div><p class="muted small">已完成 1 题 · 当前追问 1 / 2</p><h3 class="section">会话状态</h3><span class="status ${state.paused?'warning':'success'}">${state.paused?'已暂停':'进行中'}</span><p class="responsive-note">断网、刷新或 Provider 失败时保留已提交回答。</p></aside></div></div>`}
function voiceRoom(){let map={intro:['麦克风未授权','请求前先说明用途、Mock 不实际录音','同意并模拟授权','voice-grant'],recording:['正在聆听','Mock 音量波形 · 点击完成回答','完成录音','voice-asr'],asr:['ASR 转写中','正在识别 Java / RAG / Agent 技术术语…','查看转写','voice-low'],low:['低置信技术术语','“向量召回的 rerank 模型”中 rerank 置信度 61%','修正转写','voice-fix'],fixed:['转写已修正','用户将“re rank”修正为“rerank”，评分使用修正版','播放面试官追问','voice-tts'],tts:['TTS 播放中','同时提供可读文本，不依赖音频完成流程','模拟 TTS 失败','voice-fail'],fail:['TTS 服务失败','已保留问题文本和当前轮次，可重试或降级文本','切换文本模式','goto-text']};let x=map[state.voice]||map.intro;let voiceIndex={intro:0,recording:1,asr:2,low:3,fixed:4,tts:5,fail:6}[state.voice]??0;return `<div class="interview-shell">${pageHead('面试中 · 级联语音','语音面试室','ASR → 文本 Agent → TTS 的 Mock 流程；不会请求真实麦克风。',btn('文本模式','goto-text')+btn('结束','end','danger'))}<div class="room-bar"><span>Agent 与 RAG 专项 · 第 1 / 4 题</span><span class="mono">18:26</span></div><div class="room"><section class="chat"><div class="bubble ai"><strong>面试官文字</strong><br>请解释 RAG 中召回与重排的分工，以及如何评价两者。</div><div class="audio-orb ${state.voice==='recording'?'recording':state.voice==='fail'?'failed':''}" aria-label="${x[0]}">${state.voice==='recording'?'REC':state.voice==='fail'?'ERR':'VOICE'}</div><div class="card"><div class="section-head"><h2>${x[0]}</h2><span class="status ${state.voice==='fail'?'danger':state.voice==='low'?'warning':'info'}">Mock</span></div><p class="muted">${x[1]}</p>${state.voice==='intro'?notice('音频与隐私','原型不采集音频。生产方向是转写成功后尽快删除原始音频，具体 SLA 待批准。','warning'):''}<div class="btn-row">${btn(x[2],x[3],'primary')}${state.voice==='intro'?btn('拒绝并切换文本','voice-deny'):''}${state.voice==='fail'?btn('重试播放','voice-tts'):''}</div></div></section><aside class="room-aside"><h2>语音状态链</h2>${['授权','录音','ASR','修正','Agent','TTS'].map((t,i)=>`<div class="timeline-item"><div class="dot">${i+1}</div><div><strong>${t}</strong><p class="muted tiny">${state.voice==='fail'&&i===5?'失败':i<voiceIndex?'已完成':'待处理'}</p></div></div>`).join('')}</aside></div></div>`}
function sessionControl(){return pageHead('会话控制','暂停、恢复和主动结束','关键动作有明确影响、取消路径与恢复入口。')+`<div class="grid grid-3"><div class="card"><span class="status warning">面试暂停</span><h2>计时已暂停</h2><p class="muted">草稿保留，面试官不会继续提问。</p>${btn('恢复面试','goto-text','primary')}</div><div class="card"><span class="status info">恢复成功</span><h2>回到最近轮次</h2><p class="muted">没有重复问题或重复扣费。</p>${btn('查看恢复点','toast')}</div><div class="card"><span class="status danger">主动结束确认</span><h2>结束并生成部分报告？</h2><p class="muted">已完成 2 / 4 题；未作答题不评分。</p><div class="btn-row">${btn('结束并生成报告','goto-report','danger')}${btn('继续面试','goto-text')}</div></div></div>`}
function reportOverview(sample=false){return pageHead(sample?'公开示例':'面试报告','面试报告总览',sample?'公开 Mock 报告，不包含真实用户数据。':'Agent 与 RAG 专项 · 2026-08-02 · Rubric v0.3',btn('查看逐题证据','goto-evidence','primary'))+notice('报告定位','练习反馈，不是招聘结论。低置信与证据不足不会被强行计分。','info')+`<div class="section grid grid-3"><div class="card"><div class="muted small">综合练习反馈</div><div class="report-score">72</div><span class="status warning">中等置信</span></div><div class="card"><h2>技术内容</h2>${metric('正确性',76)}${metric('深度',64)}${metric('边界意识',58)}</div><div class="card"><h2>表达交付</h2>${metric('结构',82)}${metric('简洁度',68)}${metric('例子',55)}</div></div><div class="section grid grid-2"><div class="card"><h2>三项优先行动</h2><ol><li>补齐外部系统不支持幂等键时的回读与补偿。</li><li>为 RAG 召回与重排分别定义离线指标。</li><li>回答系统设计题时先讲约束，再讲取舍。</li></ol>${btn('加入学习计划','goto-learning','primary')}</div><div class="card"><h2>限制说明</h2><p>第 3 题缺少可引用证据，未判断“安全边界”维度。语音表达来自 Mock 数据，不代表真实 ASR/TTS 分析。</p>${btn('反馈评分不准确','toast')}</div></div>`}
function reportEvidence(){return pageHead('证据化反馈','逐题证据与评分','Rubric、用户原话、判断状态和行动建议逐项对应。')+`<div class="grid"><article class="card"><div class="section-head"><h2>Q2 · Agent 工具调用如何避免重复副作用？</h2><span class="status warning">部分正确</span></div><div class="grid grid-2"><div><h3>Rubric</h3><table class="table"><tbody><tr><td>幂等键</td><td>${tag('正确','success')}</td></tr><tr><td>持久化恢复点</td><td>${tag('正确','success')}</td></tr><tr><td>外部回读</td><td>${tag('部分','warning')}</td></tr><tr><td>补偿策略</td><td>${tag('证据不足','info')}</td></tr></tbody></table></div><div><h3>用户原话证据</h3><div class="evidence"><p class="quote">“我会给工具调用设计幂等键，并把调用意图和结果写入持久化状态。”</p></div><h3 class="section">行动建议</h3><p>补充“不支持幂等键”的三步策略：调用前意图记录、调用后回读、无法确认时人工处理。</p>${btn('加入专项练习','add-plan','primary')}</div></div></article></div>`}
