function adminHead(title,lede){return `<div class="admin-banner"><span>管理员 Mock 视角 · 最小权限</span><span>敏感正文默认不可见</span></div>${pageHead('管理后台',title,lede)}`}
function adminEditor(){return adminHead('创建和编辑题目','每题必须关联来源、Rubric、追问预算和审核人。')+`<form class="card"><div class="form-grid"><div class="field"><label for="qid">题目 ID</label><input id="qid" value="Q-NEW-001" readonly></div><div class="field"><label for="domain">方向</label><select id="domain"><option>Agent</option><option>RAG</option><option>MCP</option></select></div><div class="field full"><label for="title">题干</label><textarea id="title">如何设计一个可恢复、可审计的 Agent 工具调用流程？</textarea></div><div class="field full"><label for="source">参考来源与访问日期</label><input id="source" value="内部架构实践 / 2026-08-02"></div><div class="field full"><label>Rubric 评分点</label><div class="option">1. 幂等键与调用意图持久化 ${tag('必选','primary')}</div><div class="option">2. 外部回读与不确定状态 ${tag('必选','primary')}</div><div class="option">3. 补偿 / HITL / 审计 ${tag('加分')}</div></div></div><div class="btn-row section">${btn('保存草稿','toast','primary')}${btn('提交审核','goto-admin-review')}</div></form>`}
function adminReview(){return adminHead('内容审核、版本对比和发布','已发布内容修改必须产生新版本，历史报告保留旧版本。')+`<div class="grid grid-2"><div class="card"><div class="section-head"><h2>v0.3 已发布</h2>${tag('当前版本','success')}</div><p>评分点：幂等、持久化、补偿</p></div><div class="card" style="border:2px solid var(--primary)"><div class="section-head"><h2>v0.4 待审核</h2>${tag('新增','primary')}</div><p>新增：外部回读、不确定状态与人工处理</p></div></div><div class="card section"><h2>发布检查</h2><label class="checkbox"><input type="checkbox" checked>来源与许可已核对</label><label class="checkbox"><input type="checkbox" checked>Golden Set 影响已评估</label><label class="checkbox"><input type="checkbox">第二审核人确认</label><div class="btn-row section">${btn('发布 v0.4','toast','primary')}${btn('退回修改','toast')}</div></div>`}
function adminProvider(){return adminHead('Provider 状态、延迟和成本','只展示 Mock 指标；不包含真实供应商、Key、价格或调用。')+`<div class="grid grid-4">${[['LLM 主路由','99.4%','P95 2.1s','正常'],['ASR','97.8%','P95 1.8s','波动'],['TTS','94.1%','P95 2.7s','降级中'],['报告 Judge','98.9%','P95 8.4s','正常']].map(x=>`<div class="card"><span class="status ${x[3]==='正常'?'success':'warning'}">${x[3]}</span><h2>${x[0]}</h2><div class="stat">${x[1]}</div><p class="muted small">${x[2]}</p></div>`).join('')}</div>${notice('自动降级生效','TTS 错误率超过 Mock 阈值；语音问题仍以文本展示，平台失败不扣费。','warning')}<div class="section card"><h2>单位成本 Mock</h2>${metric('文本面试',42)}${metric('语音面试',71)}${metric('深度报告',56)}</div>`}
function adminGolden(){return adminHead('Golden Set 与评测质量','正确、部分、错误、证据不足与 ASR 错词均需覆盖。')+`<div class="grid grid-3"><div class="card"><div class="muted">样本数</div><div class="stat">128</div><span class="status success">达到建议下限</span></div><div class="card"><div class="muted">人工一致率</div><div class="stat">82.4%</div><span class="status success">高于 Mock 门槛 80%</span></div><div class="card"><div class="muted">证据不足识别</div><div class="stat">76.8%</div><span class="status warning">需要改进</span></div></div><div class="section table-wrap"><table class="table"><thead><tr><th>集合</th><th>覆盖</th><th>一致率</th><th>结论</th></tr></thead><tbody><tr><td>Agent 恢复</td><td>32</td><td>87%</td><td>${tag('通过','success')}</td></tr><tr><td>RAG 评测</td><td>28</td><td>81%</td><td>${tag('通过','success')}</td></tr><tr><td>ASR 技术术语</td><td>18</td><td>72%</td><td>${tag('阻断','danger')}</td></tr></tbody></table></div>`}
function adminComplaints(){return adminHead('用户投诉和评分纠错','纠错不会静默改写历史报告；形成新评测版本和通知。')+`<div class="table-wrap"><table class="table"><thead><tr><th>工单</th><th>类型</th><th>摘要</th><th>状态</th><th>操作</th></tr></thead><tbody><tr><td>FB-2031</td><td>评分不准确</td><td>“未提到 rerank”但转写有相关证据</td><td>${tag('待复核','warning')}</td><td>${btn('打开','toast','small')}</td></tr><tr><td>FB-2027</td><td>内容过时</td><td>MCP 授权描述需要更新</td><td>${tag('已分派','info')}</td><td>${btn('打开','toast','small')}</td></tr></tbody></table></div>`}
function adminDeletion(){return adminHead('隐私删除请求','显示对象范围、步骤、部分失败与最小审计结果。')+`<div class="table-wrap"><table class="table"><thead><tr><th>请求</th><th>范围</th><th>当前状态</th><th>截止</th><th>操作</th></tr></thead><tbody><tr><td>DR-240802-18</td><td>会话 + 转写 + 报告</td><td>${tag('删除外部副本','warning')}</td><td>08-05</td><td>${btn('查看步骤','toast','small')}</td></tr><tr><td>DR-240801-09</td><td>账号注销</td><td>${tag('部分失败','danger')}</td><td>已逾期 3h</td><td>${btn('处理异常','toast','small')}</td></tr></tbody></table></div>${notice('删除部分失败','对象存储已清理，外部 Provider 确认超时；用户数据保持隐藏。','danger')}`}
function adminAudit(){return adminHead('管理员敏感访问审计','默认拒绝正文访问；必须提供 reason code，并记录目标、时间和结果。')+`${notice('需要 reason code','查看用户转写属于敏感访问。仅“排查评分投诉”等批准理由可继续。','warning')}<div class="grid grid-2 section"><form class="card"><h2>申请敏感访问</h2><div class="field ${state.view==='管理员访问需要 reason code'?'error':''}"><label for="reason">Reason code</label><select id="reason"><option value="">请选择</option><option>评分投诉复核</option><option>隐私请求处理</option><option>安全事件调查</option></select>${state.view==='管理员访问需要 reason code'?'<span class="field-error" role="alert">必须选择批准的 reason code</span>':''}</div><div class="field section"><label for="case">关联工单</label><input id="case" value="FB-2031"></div><div class="btn-row section">${btn('提交访问申请','toast','primary')}${btn('取消','toast')}</div></form><div class="card"><h2>最近审计</h2><div class="timeline"><div class="timeline-item"><div class="dot">1</div><div><strong>拒绝访问</strong><p class="muted small">缺少 reason code · 20:31</p></div></div><div class="timeline-item"><div class="dot">2</div><div><strong>只读访问 4 分钟</strong><p class="muted small">评分投诉复核 · FB-2028</p></div></div></div></div></div>`}
function decisions(){let saved=JSON.parse(localStorage.getItem('mock-decisions')||'{}');return pageHead('产品评审','产品决策中心','选择仅保存在浏览器 localStorage 的 Mock 状态，不修改正式决策登记表。',btn('导出选择摘要','decision-export')+btn('恢复推荐项','decision-reset','primary'))+notice('事实边界','当前正式决策仍以 文档/决策/决策登记表.md 为准；这里的点击不构成批准。','warning')+`<div class="section decision-grid">${MOCK.decisions.map((d,i)=>{let sel=saved[i]||d[4];return `<section class="decision-card selected"><div class="section-head"><span class="status warning">${d[6]}</span><span class="tag primary">推荐 ${d[4]}</span></div><h2>${d[0]}</h2>${d.slice(1,4).map((o,j)=>{let letter=['A','B','C'][j];return `<label class="option"><input type="radio" name="decision-${i}" data-decision="${i}" value="${letter}" ${sel===letter?'checked':''}><span>${o}</span></label>`}).join('')}<div class="small"><strong>影响</strong><br><span class="muted">${d[5]}</span></div><div class="tiny mono">Mock 选择：${sel}</div></section>`}).join('')}</div>`}
function bind(){
 window.onhashchange=()=>{state.page=location.hash.slice(1)||'home';state.view='默认';render()};
 document.querySelectorAll('[data-role]').forEach(b=>b.onclick=()=>{let r=b.dataset.role;localStorage.setItem('mock-role',r);location.hash=r==='admin'?'admin-content':'dashboard'});
 document.querySelectorAll('[data-action]').forEach(b=>b.onclick=e=>action(b.dataset.action,e));
 document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{state.view=b.dataset.view;state.modal=null;render()});
 document.querySelectorAll('[data-search]').forEach(b=>b.onclick=()=>{state.query=b.dataset.search;render()});
 document.querySelectorAll('[data-decision]').forEach(r=>r.onchange=()=>{let x=JSON.parse(localStorage.getItem('mock-decisions')||'{}');x[r.dataset.decision]=r.value;localStorage.setItem('mock-decisions',JSON.stringify(x));toast('Mock 决策已保存在本浏览器');render()});
 document.getElementById('q-search')?.addEventListener('input',e=>{state.query=e.target.value});document.getElementById('q-search')?.addEventListener('keydown',e=>{if(e.key==='Enter')render()});
}
function action(a,e){const go={
 'goto-auth':'auth','goto-onboarding':'onboarding','goto-home':'home','goto-dashboard':'dashboard','goto-questions':'questions','goto-question':'question-detail','goto-practice':'practice','goto-focus':'focus-practice','goto-plan':'interview-plan','goto-text':'text-room','goto-voice':'voice-room','goto-report':'report-overview','goto-evidence':'report-evidence','goto-learning':'learning-plan','goto-usage':'usage','goto-pricing':'pricing','goto-sample':'sample-report','goto-admin-editor':'admin-editor','goto-admin-review':'admin-review'};
 if(go[a]){location.hash=go[a];return}if(a==='state-lab'){state.modal='state';render();return}if(a==='close-modal'){state.modal=null;render();return}if(a==='clear-search'){state.query='';state.view='默认';render();return}if(a==='pause'){state.paused=!state.paused;state.view=state.paused?'面试暂停':'默认';render();return}if(a==='end'){state.modal=`<div class="modal-head"><div><h2>主动结束确认</h2><p class="muted">已完成内容将生成部分报告；未作答题不评分。</p></div><button class="close" data-action="close-modal" aria-label="关闭">×</button></div><div class="btn-row">${btn('结束并生成部分报告','goto-report','danger')}${btn('继续面试','close-modal')}</div>`;render();return}if(a.startsWith('voice-')){let map={'voice-grant':'recording','voice-asr':'asr','voice-low':'low','voice-fix':'fixed','voice-tts':'tts','voice-fail':'fail'};if(a==='voice-deny'){state.view='麦克风拒绝';toast('已拒绝麦克风，自动降级到文本');location.hash='text-room';return}state.voice=map[a]||'intro';render();return}if(a==='decision-reset'){localStorage.removeItem('mock-decisions');toast('已恢复所有 Mock 推荐项');render();return}if(a==='decision-export'){toast('已生成 Mock 摘要；未写入正式文档');return}if(a==='login'){location.hash='dashboard';return}if(a==='send-answer'||a==='submit-answer'){toast('Mock 回答已提交；重复点击不会重复处理');return}if(a==='add-plan'){toast('已加入 Mock 学习计划');return}toast('这是 Mock 交互，不会调用真实服务')}
let toastTimer;function toast(msg){const t=document.getElementById('live-region');t.textContent=msg;t.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.hidden=true,3600)}
render();
